INSERT INTO workspaces (id, owner_user_id, name, slug, team, location) VALUES (1, 1, 'Manchester Business Help Centre', 'manchester-business-help-centre', 'Content & Search Team', 'Northern Quarter, Manchester');
INSERT INTO workspace_settings (workspace_id) VALUES (1);
INSERT INTO collections (id, workspace_id, name, description) VALUES (1, 1, 'Business Help Articles', 'Sixteen help articles across dental, food, fitness and property topics, written by the showcase content team.');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (1, 1, 'Booking a dental check-up in Didsbury', 'Book a dental check-up with our dentist team in Didsbury. Your appointment includes an examination, digital x-rays where needed, a hygiene polish and a written treatment plan with clear prices before any treatment begins.', 'Dental & clinics', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (2, 1, 'Ordering Sunday lunch for a group', 'Reserve a table for Sunday lunch and order from our seasonal menu. Our kitchen serves roast dishes, vegetarian options and desserts, with allergen information for every dish and group bookings for up to twenty guests.', 'Food & hospitality', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (3, 1, 'Starting a strength programme at the gym', 'Start a strength programme with a coach-led induction at the gym. Your plan builds workout sessions around squats, presses and rows, tracks your training progress weekly and adjusts weights as your fitness improves.', 'Fitness & wellness', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (4, 1, 'Booking a property viewing in Chorlton', 'Book a viewing for homes to rent or buy in Chorlton. Our property team confirms your appointment by email, shares the property details in advance and answers questions about rent, deposit and tenancy terms.', 'Property & lettings', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (5, 1, 'Dental implants: what the treatment involves', 'Dental implants replace missing teeth with a titanium post and a natural-looking crown. Treatment starts with a scan and consultation, and most patients return to work the day after the implant is placed by the dentist.', 'Dental & clinics', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (6, 1, 'Allergen information for our menu', 'Every dish on our menu lists its allergen information clearly. Tell our team about any allergy before ordering and the kitchen will prepare your food separately, with ingredients checked and labelled for your table.', 'Food & hospitality', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (7, 1, 'Cardio classes and heart-rate training', 'Our cardio classes mix cycling, rowing and intervals to build stamina and burn energy. Heart-rate zones guide each workout so members train at the right intensity, with coaches adjusting the session for every fitness level.', 'Fitness & wellness', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (8, 1, 'Understanding rent, deposits and tenancy agreements', 'Before you rent a property, check the monthly rent, the deposit protection scheme and the tenancy agreement length. Our lettings team explains every charge in writing so tenants know the full cost before signing.', 'Property & lettings', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (9, 1, 'Teeth whitening options and aftercare', 'Professional teeth whitening lifts stains from coffee, tea and red wine. The dentist checks your enamel first, applies the whitening gel safely and explains aftercare so your smile stays bright for longer.', 'Dental & clinics', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (10, 1, 'How our kitchen handles group bookings', 'Group bookings of eight or more can pre-order from a set menu so the kitchen serves every course together. Share dietary needs in advance and our team will confirm dishes, timings and the final bill split.', 'Food & hospitality', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (11, 1, 'Muscle building: protein, rest and progressive training', 'Building muscle needs progressive training, enough protein and proper rest between gym sessions. Our coaches design workout plans that add small weight increases weekly and track strength gains across each training block.', 'Fitness & wellness', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (12, 1, 'Selling your home: valuation and viewings', 'Selling your home starts with an accurate valuation based on recent local sales. Our property team photographs each room, writes the listing details and arranges viewings that suit buyers and sellers alike.', 'Property & lettings', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (13, 1, 'Children''s dentistry: first visits made easy', 'Children''s first dental visits should feel relaxed and friendly. Our dentist team uses short check-up appointments, fluoride protection and simple brushing guidance so young patients build healthy teeth habits early.', 'Dental & clinics', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (14, 1, 'Seasonal desserts and our baking kitchen', 'Our baking kitchen prepares seasonal desserts daily, from flour-and-butter pastry to baked fruit crumbles. The dessert menu changes with the market, and every recipe lists sugar content and allergen notes for guests.', 'Food & hospitality', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (15, 1, 'Recovery: stretching, sleep and rest days', 'Recovery days help muscles repair after hard training. Gentle stretching, good sleep and lighter gym sessions keep workout progress steady and reduce injury risk for members following a weekly fitness programme.', 'Fitness & wellness', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (16, 1, 'Property management for landlords', 'Our property management service handles rent collection, inspections and repairs for landlords. Tenants report issues through one contact, and our team arranges trusted tradespeople while keeping landlords updated on every property.', 'Property & lettings', 'Seeded collection');
INSERT INTO collections (id, workspace_id, name, description) VALUES (2, 1, 'Topic Check Set', 'Nine three-word documents in three topics with disjoint vocabularies — the hand-verifiable fixture set for scores, buckets and clusters.');
