INSERT INTO collections (id, workspace_id, name, description) VALUES (3, 1, 'Support Answer Drafts', 'Six short support answers covering accounts, deliveries, payments and bookings.');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (26, 3, 'Resetting your account password', 'Reset your account password from the sign-in page. We email a secure link that expires in one hour, and your account stays locked until the new password is set and confirmed.', 'accounts', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (27, 3, 'Tracking a delivery', 'Track your delivery with the reference in your confirmation email. The courier updates the parcel status at each depot, and delivery slots can be changed until the evening before arrival.', 'deliveries', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (28, 3, 'Paying an invoice by card', 'Pay an invoice online by card in a few minutes. The payment page shows the invoice total, accepts major cards and emails a receipt once the payment clears your bank.', 'payments', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (29, 3, 'Changing a booking time', 'Change your booking time from your account page up to a day before the appointment. The new time is confirmed by email and the original booking slot is released straight away.', 'bookings', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (30, 3, 'Updating your contact details', 'Update your contact details so confirmations reach the right inbox. Email address changes need one confirmation click, while phone number changes are verified with a short code by text.', 'accounts', 'Seeded collection');
INSERT INTO documents (id, collection_id, title, body, topic, source) VALUES (31, 3, 'Refunds for cancelled orders', 'Refunds for cancelled orders return to the original payment card within five working days. You receive an email when the refund is issued, showing the order reference and refunded amount.', 'payments', 'Seeded collection');
